const n = query.n ?? 4;
const text = query.text ?? '';
try {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://nltk-tools:8000/char_ngrams',
    qs: { n, top_k: 50 },
    body: { text },
    json: true,
  });
  return JSON.stringify(data);
} catch (e) {
  return `Tool error: ${e.message}`;
}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "text": { "type": "string", "description": "The full document text to analyze." },
    "n": { "type": "number", "description": "The character n-gram size (3, 4, or 5). Default 4." }
  },
  "required": ["text"]
}

